<?php $logoData=$asset($logo); ?>
<!doctype html><html><head><meta charset="UTF-8"><title><?= $escape($title) ?></title><style>@page{margin:30px}body{font-family:DejaVu Sans,Arial,sans-serif;font-size:9px;color:#222}.head{border-bottom:3px solid #222;padding-bottom:12px;margin-bottom:18px}.logo{max-height:55px;max-width:150px}.company{font-size:18px;font-weight:bold}.invoice-title{font-size:24px;text-align:right}.info{margin-bottom:18px}table{width:100%;border-collapse:collapse}thead{display:table-header-group}th{background:#222;color:#fff;padding:7px;text-align:left}td{padding:7px;border-bottom:1px solid #ddd}.totalbox{margin-top:15px;margin-left:auto;width:45%;border:1px solid #ccc;padding:10px}.total{font-size:15px;font-weight:bold}.footer{margin-top:25px;border-top:1px solid #ccc;padding-top:8px;font-size:8px}</style></head><body><div class="head"><?php if($logoData): ?><img class="logo" src="<?= $escape($logoData) ?>"><br><?php endif; ?><span class="company"><?= $escape($header ?: 'Invoice') ?></span><span class="invoice-title"><?= $escape($title) ?></span><?php if($showGeneratedMeta): ?><div>Generated <?= $escape($generated) ?> by <?= $escape($generatedBy) ?></div><?php endif; ?></div><table><thead><tr><?php foreach($columns as $c): ?><th><?= $escape($c['label']) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($rows as $r): ?><tr><?php foreach($columns as $c): ?><td style="text-align:<?= $escape($c['align']??'left') ?>"><?= $escape($format($value($r,$c['key']),$c)) ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table><?php if($calculations): ?><div class="totalbox"><?php foreach($calculations as $k=>$v): ?><div><?= $escape($k) ?>: <span class="total"><?= $escape($v) ?></span></div><?php endforeach; ?></div><?php endif; ?><?php if($footer): ?><div class="footer"><?= nl2br($escape($footer)) ?></div><?php endif; ?></body></html>
